.VerifyChanges <- function(path,
                           private) {
  # generated by make, local only, or secret: never compared
  skip <- paste(
    c(
      "^\\.git/",
      "^\\.verify/",
      "^\\.sif/",
      "^\\.setup/data-external/",
      "^\\.setup/data-cache/",
      "^\\.library/",
      "^\\.claude/",
      "^\\.Rproj\\.user/",
      "^\\.quarto/",
      "^detritus",
      "^docs/",
      "^pkgdown/",
      "^quarto/",
      "^\\.setup/build/",
      "^\\.setup/scripts/rproject\\.lock$",
      "^\\.setup/quarto/bib/",
      "^latexmkrc$",
      "^man/",
      "^src/",
      "^vignettes/vignettes\\.bib$",
      "^vignettes/fig-vignettes-",
      "^vignettes/.*\\.orig$",
      "^\\.setup/latex/pdf/",
      # figures/psu/ holds uploaded marks and photos, not generated figures
      "^\\.setup/latex/figures/(?!psu/)",
      "^\\.setup/data-analysis/.*\\.txt$",
      "^data/.*\\.rda$",
      "^NAMESPACE$",
      "^AGENTS\\.md$",
      "^CLAUDE\\.md$",
      "^\\.github/copilot-instructions\\.md$",
      "^\\.Rbuildignore$",
      "^project\\.Rproj$",
      "^README\\.md$",
      "^CITATION\\.cff$",
      "^LICENSE",
      "^R/RcppExports\\.R$",
      "bib\\.bib$",
      "^\\.Renviron$",
      "^\\.Rprofile$",
      # secret files, but not the secretscan files (a workflow, a report)
      "secrets(?!can)",
      "TEMPDIR"
    ),
    collapse = "|"
  )
  files <- function(root) {
    out <- list.files(
      path = root,
      all.files = TRUE,
      recursive = TRUE,
      no.. = TRUE
    )
    out[!grepl(pattern = skip, x = out, perl = TRUE)]
  }
  candidates <- sort(x = union(x = files(path), y = files(private)))
  # vignettes knitted from .setup/vignettes/*.orig are generated;
  # hand-written vignettes are compared
  orig <- list.files(
    path = file.path(c(path, private), ".setup", "vignettes"),
    pattern = "\\.orig$"
  )
  candidates <- setdiff(
    x = candidates,
    y = file.path(
      "vignettes",
      sub(pattern = "\\.orig$", replacement = "", x = orig)
    )
  )
  # tier 2 template files are written by make (Template()), not uploaded,
  # but the Makefile and the .gitignore files, kept in Overleaf
  type <- .TemplateType(path = path)
  if (!is.null(x = type)) {
    files <- .TemplateFiles(
      type = type,
      settings = .TemplateSettings(path = path)
    )
    candidates <- setdiff(
      x = candidates,
      y = files$path[!.TemplateKept(files = files)]
    )
  }
  status <- vapply(
    X = candidates,
    FUN = function(file) {
      .VerifyCompare(
        path = path,
        private = private,
        file = file
      )
    },
    FUN.VALUE = character(length = 1)
  )
  status[status != "match"]
}
